// Builds lib/ml/embedderHtml.js: one self-contained HTML page for the hidden ML WebView.
// onnxruntime-web's ESM bundle is inlined as a module script with its `export{...}`
// rewritten to `window.ort = {...}`, then scripts/embedder-page.js runs once it exists.
// Run after changing either file:  node scripts/build-embedder.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
let ortSrc = readFileSync(join(root, 'vendor/onnxruntime-web/ort.wasm.bundle.min.mjs'), 'utf8');
const page = readFileSync(join(root, 'scripts/embedder-page.js'), 'utf8');

ortSrc = ortSrc.replace(/\/\/# sourceMappingURL=.*$/m, '');
const exportMatch = ortSrc.match(/export\{([^}]*)\};?\s*$/);
if (!exportMatch) throw new Error('onnxruntime-web bundle: trailing export{} not found');
const fields = exportMatch[1].split(',').map((part) => {
  const [local, name] = part.trim().split(/\s+as\s+/);
  return `${JSON.stringify(name ?? local)}:${local}`;
});
ortSrc = ortSrc.slice(0, exportMatch.index) + `window.ort={${fields.join(',')}};window.__ortReady&&window.__ortReady();`;

const safe = (js) => js.replace(/<\/script/gi, '<\\/script');
const html = `<!doctype html><html><head><meta charset="utf-8"></head><body>
<script>window.__ortReady=function(){var s=document.createElement('script');s.textContent=${JSON.stringify(safe(page))};document.body.appendChild(s);};</script>
<script type="module">${safe(ortSrc)}</script>
</body></html>`;

writeFileSync(join(root, 'lib/ml/embedderHtml.js'),
  '// GENERATED by scripts/build-embedder.mjs — do not edit.\n' +
  'export default ' + JSON.stringify(html) + ';\n');
if (process.env.EMBEDDER_TEST_OUT) writeFileSync(process.env.EMBEDDER_TEST_OUT, html);
console.log('embedderHtml.js', html.length, 'chars');
